type ClientsMarqueeProps = {
  clients: string[];
};

export default function ClientsMarquee({ clients }: ClientsMarqueeProps) {
  return (
    <section
      id="clients"
      className="border-y border-gold/30 py-16 sm:py-20 lg:py-24"
    >
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between gap-4">
          <h2 className="font-heading text-2xl font-semibold">Нам доверяют</h2>
          <p className="text-sm text-anthracite/70">
            Реальные клиенты, долгосрочные партнерства
          </p>
        </div>
      </div>
      <div className="mt-10 overflow-hidden">
        <div className="marquee flex w-[200%] gap-6">
          {[0, 1].map((row) => (
            <ul
              key={row}
              className="flex w-1/2 flex-wrap items-center justify-around gap-6"
              aria-label="Список клиентов"
            >
              {clients.map((client, index) => (
                <li
                  key={`${client}-${row}-${index}`}
                  className="rounded-full border border-gold/40 px-6 py-2 text-sm text-anthracite/80"
                >
                  {client}
                </li>
              ))}
            </ul>
          ))}
        </div>
      </div>
    </section>
  );
}
