type PortfolioItem = {
  title: string;
  image: string;
  duration: string;
  material: string;
  format: string;
};

type PortfolioProps = {
  items: PortfolioItem[];
};

export default function Portfolio({ items }: PortfolioProps) {
  return (
    <section id="portfolio" className="py-16 sm:py-20 lg:py-24">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <div className="flex flex-wrap items-end justify-between gap-6">
          <div>
            <p className="text-sm uppercase tracking-[0.3em] text-anthracite/60">
              Портфолио
            </p>
            <h2 className="mt-3 font-heading text-3xl font-semibold sm:text-4xl">
              Реализованные проекты, которые говорят сами за себя
            </h2>
          </div>
          <a
            href="#form"
            className="focus-ring rounded-full border border-gold/70 px-5 py-2 text-sm font-semibold text-anthracite transition hover:border-gold"
          >
            Хочу похожий проект
          </a>
        </div>
      </div>

      <div className="mt-10 overflow-x-auto pb-4">
        <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
          <div className="flex gap-6 snap-x snap-mandatory">
            {items.map((item) => (
              <article
                key={item.title}
                className="min-w-[260px] flex-1 snap-start overflow-hidden rounded-3xl border border-gold/25 bg-white/70"
              >
                <div className="relative h-48 w-full overflow-hidden sm:h-56">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="h-full w-full object-cover"
                    loading="lazy"
                  />
                </div>
                <div className="space-y-4 p-6">
                  <h3 className="font-heading text-lg font-semibold">{item.title}</h3>
                  <dl className="grid gap-3 text-sm text-anthracite/70">
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Срок</dt>
                      <dd>{item.duration}</dd>
                    </div>
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Материал</dt>
                      <dd>{item.material}</dd>
                    </div>
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Формат</dt>
                      <dd>{item.format}</dd>
                    </div>
                  </dl>
                </div>
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
